-- Fields the running app already saves, which 001 does not store.
-- Apply this file only after explicit approval. Do not run it against Neon from the app.
--
-- Homi uses Neon PostgreSQL as its only database. This file is not for any other database.
-- Category colors and stable keys stay in PostgreSQL so the screens can keep their ids.
-- Expense, payment, settlement, and task ids generated by the app are stored beside the uuid keys.
-- Balances are not stored. The ledger still calculates them.

ALTER TABLE households
  ADD COLUMN default_viewer_bps integer NOT NULL DEFAULT 10000;

ALTER TABLE households
  ADD CONSTRAINT households_default_viewer_bps_check CHECK (default_viewer_bps BETWEEN 0 AND 10000);

ALTER TABLE expense_categories
  ADD COLUMN category_key text,
  ADD COLUMN color text;

UPDATE expense_categories
SET category_key = id::text
WHERE category_key IS NULL;

UPDATE expense_categories
SET color = '#6f8b80'
WHERE color IS NULL;

ALTER TABLE expense_categories
  ALTER COLUMN category_key SET NOT NULL,
  ALTER COLUMN color SET NOT NULL;

ALTER TABLE expense_categories
  ADD CONSTRAINT expense_categories_color_present CHECK (length(btrim(color)) > 0);

CREATE UNIQUE INDEX expense_categories_key_unique
  ON expense_categories (household_id, category_key);

ALTER TABLE expenses
  ADD COLUMN external_id text;

UPDATE expenses
SET external_id = id::text
WHERE external_id IS NULL;

ALTER TABLE expenses
  ALTER COLUMN external_id SET NOT NULL;

CREATE UNIQUE INDEX expenses_household_external_id_unique
  ON expenses (household_id, external_id);

ALTER TABLE expense_payments
  ADD COLUMN external_id text;

UPDATE expense_payments
SET external_id = id::text
WHERE external_id IS NULL;

ALTER TABLE expense_payments
  ALTER COLUMN external_id SET NOT NULL;

CREATE UNIQUE INDEX expense_payments_external_id_unique
  ON expense_payments (external_id);

ALTER TABLE settlements
  ADD COLUMN external_id text;

UPDATE settlements
SET external_id = id::text
WHERE external_id IS NULL;

ALTER TABLE settlements
  ALTER COLUMN external_id SET NOT NULL;

CREATE UNIQUE INDEX settlements_household_external_id_unique
  ON settlements (household_id, external_id);

ALTER TABLE tasks
  ADD COLUMN external_id text;

UPDATE tasks
SET external_id = id::text
WHERE external_id IS NULL;

ALTER TABLE tasks
  ALTER COLUMN external_id SET NOT NULL;

CREATE UNIQUE INDEX tasks_household_external_id_unique
  ON tasks (household_id, external_id);
